// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        (bool s, ) = address(c).call{value: 1 ether}("");
        require(s, "deposit failed");

        address nonOwner = address(0x123);
        vm.deal(nonOwner, 1);
        vm.prank(nonOwner);
        bool ok;
        try c.withdraw(1 ether) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok, "Non-owner should not be able to withdraw");
    }
}
